def sum_first(values, n):
    """返回列表前 n 个元素之和（n<=0 时为 0）。"""
    if n <= 0:
        return 0
    return sum(values[:n])

L2-S1-02.code:
def average(values):
    """返回算术平均值；空列表必须抛 ValueError。"""
    if not values:
        raise ValueError("average() requires a non-empty list")
    return sum(values) / len(values)

L2-S1-03.code:
def same_value(a, b):
    """仅当 a 与 b 的类型与取值都相同时返回 True（True 与 1 不算相同）。"""
    if type(a) != type(b):
        return False
    return a == b

L2-S1-05.code:
def safe_div(a, b):
    """返回 a / b；b 为 0（含 0.0）时返回 None。"""
    if b == 0:
        return None
    return a / b

L2-S1-06.code:
def trim_edges(text, k):
    """去掉两端各 k 个字符；2*k >= len(text) 时返回空串。"""
    if k <= 0:
        return text
    if 2 * k >= len(text):
        return ""
    return text[k:len(text) - k]

L2-S1-07.code:
def rank_players(rows):
    """按分数降序排名；分数相同时保持输入顺序。"""
    return sorted(rows, key=lambda row: -row[1])

L2-S1-08.code:
def tally(words):
    """统计每个词出现次数并返回字典。"""
    counts = {}
    for word in words:
        counts[word] = counts.get(word, 0) + 1
    return counts

L2-S1-09.code:
def factorial(n):
    """n 的阶乘；n 必须是非负整数，否则抛 ValueError。"""
    if n < 0:
        raise ValueError("factorial() requires n >= 0")
    if n <= 1:
        return 1
    return n * factorial(n - 1)

L2-S1-10.code:
def price_with_tax(base, rate):
    """返回含税价，四舍五入到 2 位小数。"""
    return round(base * (1 + rate), 2)

L2-S1-11.code:
def sum_ints(values):
    """只累加真正的整数；布尔值（True/False）不计入。"""
    total = 0
    for value in values:
        if isinstance(value, bool):
            continue
        total += value
    return total

L2-S1-12.code:
def safe_index(items, index):
    """返回 items[index]；越界返回 None，索引类型非法抛 TypeError。"""
    try:
        return items[index]
    except IndexError:
        return None

L2-S1-13.code:
def in_range(value, low, high):
    """判断 value 是否落在闭区间 [low, high] 内。"""
    return low <= value <= high

L2-S1-14.code:
def dedupe(items):
    """去重，并保持元素首次出现的顺序。"""
    out = []
    for item in items:
        if item not in out:
            out.append(item)
    return out

L2-S1-15.code:
def wrap(value, size):
    """把 value 折回 [0, size) 区间（负数也要得到非负结果）。"""
    return value % size

L2-S1-16.code:
def smallest(values):
    """返回最小值；空列表必须抛 ValueError。"""
    if not values:
        raise ValueError("smallest() requires a non-empty list")
    best = values[0]
    for value in values:
        if value < best:
            best = value
    return best

L2-S1-17.code:
def contains_ci(text, needle):
    """判断 needle 是否出现在 text 中（忽略大小写）。"""
    return needle.lower() in text.lower()

L2-S1-18.code:
def midpoint(a, b):
    """返回 a 与 b 的中点（允许小数）。"""
    return (a + b) / 2

L2-S1-19.code:
def all_positive(values):
    """判断是否所有元素都 > 0（空列表视为 True）。"""
    for value in values:
        if value <= 0:
            return False
    return True
